import React, { useState, useEffect } from 'react';
import { shoppingAPI } from '../utils/api';

interface ShoppingList {
  id: number;
  title: string;
  status: string;
  auto_generated: boolean;
  sent_via_email: boolean;
  created_at: string;
}

interface ShoppingItem {
  id: number;
  item_name: string;
  quantity: number;
  unit: string;
  estimated_cost: number;
  checked: boolean;
}

const ShoppingPage: React.FC = () => {
  const [lists, setLists] = useState<ShoppingList[]>([]);
  const [selectedList, setSelectedList] = useState<ShoppingList | null>(null);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [newList, setNewList] = useState({
    title: '',
    items: [{ item_name: '', quantity: 1, unit: 'adet', estimated_cost: 0 }]
  });

  useEffect(() => {
    loadShoppingLists();
  }, []);

  const loadShoppingLists = async () => {
    try {
      const response = await shoppingAPI.getAll();
      setLists(response.data);
    } catch (error) {
      console.error('Error loading shopping lists:', error);
    } finally {
      setLoading(false);
    }
  };

  const generateFromInventory = async () => {
    try {
      const response = await shoppingAPI.generateFromInventory();
      loadShoppingLists();
      alert('Düşük stoklu ürünlerden alışveriş listesi oluşturuldu!');
    } catch (error) {
      console.error('Error generating list:', error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await shoppingAPI.create(newList);
      setNewList({
        title: '',
        items: [{ item_name: '', quantity: 1, unit: 'adet', estimated_cost: 0 }]
      });
      setShowForm(false);
      loadShoppingLists();
    } catch (error) {
      console.error('Error creating shopping list:', error);
    }
  };

  const addItem = () => {
    setNewList({
      ...newList,
      items: [...newList.items, { item_name: '', quantity: 1, unit: 'adet', estimated_cost: 0 }]
    });
  };

  const removeItem = (index: number) => {
    const updatedItems = newList.items.filter((_, i) => i !== index);
    setNewList({ ...newList, items: updatedItems });
  };

  const updateItem = (index: number, field: string, value: any) => {
    const updatedItems = newList.items.map((item, i) => 
      i === index ? { ...item, [field]: value } : item
    );
    setNewList({ ...newList, items: updatedItems });
  };

  const sendByEmail = async (listId: number) => {
    const emails = prompt('E-posta adreslerini virgülle ayırarak girin:');
    if (emails) {
      try {
        await shoppingAPI.sendByEmail(listId, emails.split(',').map(e => e.trim()));
        alert('Alışveriş listesi e-posta ile gönderildi!');
        loadShoppingLists();
      } catch (error) {
        console.error('Error sending email:', error);
      }
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'draft': return '#6c757d';
      case 'sent': return '#007bff';
      case 'completed': return '#28a745';
      default: return '#6c757d';
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case 'draft': return 'Taslak';
      case 'sent': return 'Gönderildi';
      case 'completed': return 'Tamamlandı';
      default: return status;
    }
  };

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <h1 style={styles.title}>Alışveriş Listeleri</h1>
        <div style={styles.headerActions}>
          <button 
            style={styles.generateButton}
            onClick={generateFromInventory}
          >
            📦 Stoktan Oluştur
          </button>
          <button 
            style={styles.addButton}
            onClick={() => setShowForm(!showForm)}
          >
            {showForm ? 'İptal' : '+ Yeni Liste'}
          </button>
        </div>
      </header>

      {/* New List Form */}
      {showForm && (
        <div style={styles.formCard}>
          <h2 style={styles.formTitle}>Yeni Alışveriş Listesi</h2>
          <form onSubmit={handleSubmit} style={styles.form}>
            <div style={styles.formGroup}>
              <label style={styles.label}>Liste Adı</label>
              <input
                type="text"
                style={styles.input}
                value={newList.title}
                onChange={(e) => setNewList({...newList, title: e.target.value})}
                placeholder="Örn: Haftalık Alışveriş"
                required
              />
            </div>

            <div style={styles.itemsSection}>
              <div style={styles.itemsHeader}>
                <h3 style={styles.itemsTitle}>Ürünler</h3>
                <button type="button" style={styles.addItemButton} onClick={addItem}>
                  + Ürün Ekle
                </button>
              </div>

              {newList.items.map((item, index) => (
                <div key={index} style={styles.itemRow}>
                  <input
                    type="text"
                    style={styles.itemInput}
                    placeholder="Ürün adı"
                    value={item.item_name}
                    onChange={(e) => updateItem(index, 'item_name', e.target.value)}
                    required
                  />
                  <input
                    type="number"
                    style={styles.quantityInput}
                    placeholder="Miktar"
                    value={item.quantity}
                    onChange={(e) => updateItem(index, 'quantity', Number(e.target.value))}
                    min="0.1"
                    step="0.1"
                    required
                  />
                  <select
                    style={styles.unitSelect}
                    value={item.unit}
                    onChange={(e) => updateItem(index, 'unit', e.target.value)}
                  >
                    <option value="adet">Adet</option>
                    <option value="kg">Kg</option>
                    <option value="lt">Litre</option>
                    <option value="paket">Paket</option>
                    <option value="kutu">Kutu</option>
                  </select>
                  <input
                    type="number"
                    style={styles.priceInput}
                    placeholder="Tahmini fiyat"
                    value={item.estimated_cost}
                    onChange={(e) => updateItem(index, 'estimated_cost', Number(e.target.value))}
                    min="0"
                    step="0.01"
                  />
                  {newList.items.length > 1 && (
                    <button
                      type="button"
                      style={styles.removeButton}
                      onClick={() => removeItem(index)}
                    >
                      ×
                    </button>
                  )}
                </div>
              ))}
            </div>

            <button type="submit" style={styles.submitButton}>
              Liste Oluştur
            </button>
          </form>
        </div>
      )}

      {/* Shopping Lists */}
      <div style={styles.listsGrid}>
        {loading ? (
          <div style={styles.loading}>Yükleniyor...</div>
        ) : lists.length === 0 ? (
          <div style={styles.emptyState}>
            <p>Henüz alışveriş listesi yok</p>
            <p>Yeni liste oluşturun veya stoktan otomatik oluşturun</p>
          </div>
        ) : (
          lists.map(list => (
            <div key={list.id} style={styles.listCard}>
              <div style={styles.listHeader}>
                <h3 style={styles.listTitle}>{list.title}</h3>
                <div style={styles.listBadges}>
                  {list.auto_generated && (
                    <span style={styles.autoBadge}>Otomatik</span>
                  )}
                  <span 
                    style={{
                      ...styles.statusBadge,
                      backgroundColor: getStatusColor(list.status)
                    }}
                  >
                    {getStatusText(list.status)}
                  </span>
                </div>
              </div>

              <div style={styles.listMeta}>
                <span style={styles.listDate}>
                  {new Date(list.created_at).toLocaleDateString('tr-TR')}
                </span>
                {list.sent_via_email && (
                  <span style={styles.emailSent}>📧 E-posta gönderildi</span>
                )}
              </div>

              <div style={styles.listActions}>
                <button 
                  style={styles.viewButton}
                  onClick={() => setSelectedList(list)}
                >
                  👁️ Görüntüle
                </button>
                {!list.sent_via_email && (
                  <button 
                    style={styles.emailButton}
                    onClick={() => sendByEmail(list.id)}
                  >
                    📧 E-posta Gönder
                  </button>
                )}
              </div>
            </div>
          ))
        )}
      </div>

      {/* List Detail Modal */}
      {selectedList && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <div style={styles.modalHeader}>
              <h2 style={styles.modalTitle}>{selectedList.title}</h2>
              <button 
                style={styles.closeButton}
                onClick={() => setSelectedList(null)}
              >
                ×
              </button>
            </div>
            <div style={styles.modalBody}>
              <p>Liste detayları burada gösterilecek...</p>
              <p>Bu özellik yakında tamamlanacak.</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const styles = {
  container: {
    padding: '24px',
    maxWidth: '1200px',
    margin: '0 auto',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '24px',
  },
  title: {
    fontSize: '28px',
    fontWeight: '700',
    color: '#2c3e50',
    margin: 0,
  },
  headerActions: {
    display: 'flex',
    gap: '12px',
  },
  generateButton: {
    backgroundColor: '#17a2b8',
    color: '#fff',
    border: 'none',
    borderRadius: '8px',
    padding: '12px 16px',
    fontSize: '14px',
    fontWeight: '600',
    cursor: 'pointer',
  },
  addButton: {
    backgroundColor: '#007bff',
    color: '#fff',
    border: 'none',
    borderRadius: '8px',
    padding: '12px 20px',
    fontSize: '14px',
    fontWeight: '600',
    cursor: 'pointer',
  },
  formCard: {
    backgroundColor: '#fff',
    borderRadius: '12px',
    padding: '24px',
    marginBottom: '24px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
    border: '1px solid #e9ecef',
  },
  formTitle: {
    fontSize: '20px',
    fontWeight: '600',
    color: '#2c3e50',
    marginBottom: '20px',
  },
  form: {
    display: 'flex',
